    def _plot_bivariate(self, x_var, y_var, ax, func, hue_var, dropna, **kwargs):
        """Draw a bivariate plot on the specified axes."""
        if "hue" not in signature(func).parameters:
            self._plot_bivariate_iter_hue(x_var, y_var, ax, func,
                                          hue_var=hue_var, dropna=dropna,
                                          **kwargs)
            return

        kwargs = kwargs.copy()
        if is_seaborn_func(func):
            kwargs["ax"] = ax
        else:
            plt.sca(ax)

        axes_vars = compute_plot_variables(x_var, y_var, hue_var)
        x, y, plot_data = resolve_bivariate_data(
            self.data, x_var, y_var, axes_vars, dropna
        )
        hue = get_hue_values(plot_data, hue_var)

        if "hue" not in kwargs:
            kwargs.update(build_hue_kwargs(
                hue, self._hue_order, self._orig_palette
            ))
        func(x=x, y=y, **kwargs)

        self._update_legend_data(ax)

